import numpy as np

def make_state(agent, ball=None, reward=None, prev=None):
    x = np.zeros(500)
    # wall border in obstacle channel
    for r in range(10):
        for c in range(10):
            if r in (0, 9) or c in (0, 9):
                x[(r * 10 + c) * 5 + 3] = 1.0
    for (r, c) in agent:
        x[(r * 10 + c) * 5 + 0] = 1.0
    if ball:
        for (r, c) in ball:
            x[(r * 10 + c) * 5 + 1] = 1.0
    if reward:
        for (r, c) in reward:
            x[(r * 10 + c) * 5 + 2] = 1.0
    if prev is None:
        prev = list(agent) + (list(ball) if ball else [])
    for (r, c) in prev:
        x[(r * 10 + c) * 5 + 4] = 1.0
    return x

tests = [
    ("A(4,4) B(2,4) above", (4, 4), (2, 4)),
    ("A(4,4) B(6,4) below", (4, 4), (6, 4)),
    ("A(4,4) B(4,1) left ", (4, 4), (4, 1)),
    ("A(4,4) B(4,7) right", (4, 4), (4, 7)),
    ("A(4,4) no ball     ", (4, 4), None),
    ("A(5,5) B(2,5) above", (5, 5), (2, 5)),
    ("A(5,5) B(8,5) below", (5, 5), (8, 5)),
    ("A(5,5) B(5,2) left ", (5, 5), (5, 2)),
    ("A(5,5) B(5,8) right", (5, 5), (5, 8)),
    ("A(8,5) B(8,2) left ", (8, 5), (8, 2)),
    ("A(8,5) B(8,8) right", (8, 5), (8, 8)),
]

X = np.array([make_state([a], [b] if b else None) for _, a, b in tests])
out = forward(X)
e = np.exp(out - out.max(axis=1, keepdims=True))
p = e / e.sum(axis=1, keepdims=True)

for (lab, _, _), pr in zip(tests, p):
    print(lab, "-> argmax", int(np.argmax(pr)), "probs", np.round(pr, 3))

import numpy as np

def make_obs(paddle_center, ball_row, paddle_type):
    x = np.zeros((10,10,5), dtype=np.float32)
    # border walls
    x[0,:,3] = 1; x[9,:,3] = 1; x[:,0,3] = 1; x[:,9,3] = 1
    # paddle
    if paddle_type == 'bar3':
        for r in range(paddle_center-1, paddle_center+2):
            if 1 <= r <= 8:
                x[r,1,0] = 1
    else:
        x[paddle_center,1,0] = 1
    # ball current
    x[ball_row,2,1] = 1
    # previous frame: previous ball at col 3, previous paddle same as current
    x[ball_row,3,4] = 1
    if paddle_type == 'bar3':
        for r in range(paddle_center-1, paddle_center+2):
            if 1 <= r <= 8:
                x[r,1,4] = 1
    else:
        x[paddle_center,1,4] = 1
    return x.flatten()

centers = [2,4,6]
ball_rows = list(range(1,9))
X = []
meta = []
for pt in ['bar3','single']:
    for pc in centers:
        for br in ball_rows:
            X.append(make_obs(pc, br, pt))
            meta.append((pt,pc,br))
X = np.array(X)
logits = forward(X)
e = np.exp(logits - logits.max(axis=1, keepdims=True))
probs = e / e.sum(axis=1, keepdims=True)
arg = np.argmax(probs, axis=1)

for pt in ['bar3','single']:
    print(f"--- {pt} ---")
    print("      br: " + " ".join(f"{br:2d}" for br in ball_rows))
    for pc in centers:
        row = []
        for br in ball_rows:
            idx = meta.index((pt,pc,br))
            row.append(arg[idx])
        print(f"pc={pc}:   " + " ".join(f"{a:2d}" for a in row))

print("--- bar3 pc=4 probs ---")
for br in ball_rows:
    idx = meta.index(('bar3',4,br))
    print(f"br={br}: arg={arg[idx]} probs={np.round(probs[idx],3)}")
